  for (auto r : fonts) check(ShardFontHidden(r.name, r.seed) == r.hidden, "font");
  // Windows cohorts protect the entire documented base set for every
  // cohort, while optional installation classes change atomically. Historical
  // non-Windows goldens above remain frozen and are not used by Windows.
  for (uint32_t seed : {1u, 2u, 3u, 4u, 42u, 43u, 0xffffffffu}) {
    for (const auto core : kWindowsBaseFontNamesV1)
      check(!ShardWindowsFontHiddenV1(core, seed), "Windows core font retained");
    const bool packs_hidden = ShardWindowsFontHiddenV1("Meiryo", seed);
    for (const auto optional : kWindowsSupplementalFontNamesV1) {
      bool core = false;
      for (const auto protected_name : kWindowsBaseFontNamesV1)
        core |= AsciiEqual(optional, protected_name);
      for (const auto protected_name : kProtectedFontNames)
        core |= AsciiEqual(optional, protected_name);
      if (!core)
        check(ShardWindowsFontHiddenV1(optional, seed) == packs_hidden,
              "Windows supplemental installation is atomic");
    }
    check(ShardWindowsFontHiddenV1("Agency FB", seed) ==
              ShardWindowsFontHiddenV1("Lucida Bright", seed),
          "Windows application installation is atomic");
    check(!ShardWindowsFontHiddenV1("segoe ui light", seed),
          "Windows core comparison is case insensitive");
  }
  check(!ShardWindowsFontHiddenV1("Agency FB", 0), "zero seed native");
  check(ShardWindowsFontHiddenV1("Agency FB", 1), "application masking retained");
  check(!ShardWindowsFontHiddenV1("Agency FB", 2), "application cohort retained");
  check(ShardWindowsFontHiddenV1("Meiryo", 2), "optional masking retained");
  check(!ShardWindowsFontHiddenV1("Meiryo", 1), "optional cohort retained");
  // Windows font package v2 compiled installation regressions.
  const uint32_t package_masks[] = {0,1,3,5,7,9,11,13,15,2,4,6};
  for (uint32_t profile=0;profile<12;++profile) {
    const uint32_t seed=120u+profile;
    for (const auto core:kWindowsSystemFontNamesV2)
      check(!ShardWindowsFontHiddenV2(core,seed), "Windows complete system font retained");
    for (const auto app:{"Century","Century Gothic","Agency FB","MS Outlook","MT Extra","Lucida Bright","Haettenschweiler","Lucida Sans","MS Reference Specialty","Monotype Corsiva","Pristina"})
      check(ShardWindowsFontHiddenV2(app,seed)==((package_masks[profile]&1u)==0), "Office installation atomic");
    for (const auto font:{"Noto Sans JP","Noto Sans JP Black","NotoSansJP-ExtraLight"})
      check(ShardWindowsFontHiddenV2(font,seed)==((package_masks[profile]&2u)==0), "Noto Sans installation atomic");
    for (const auto font:{"Noto Serif JP","Noto Serif JP Bold","NotoSerifJP-Black"})
      check(ShardWindowsFontHiddenV2(font,seed)==((package_masks[profile]&4u)==0), "Noto Serif installation atomic");
    for (const auto font:{"Liberation Sans","Liberation Serif Bold","LiberationMono-Regular"})
      check(ShardWindowsFontHiddenV2(font,seed)==((package_masks[profile]&8u)==0), "Liberation installation atomic");
    check(!ShardWindowsFontHiddenV2("Unknown Newly Installed Font",seed), "Unclassified font retained");
  }
  for (const auto core:{"Yu Gothic UI","Yu Gothic UI Bold","YuGothicUI-Regular","Segoe UI Variable Display Semib"}) {
    check(WindowsFontListedV2(core,kWindowsSystemFontNamesV2), "System family and face alias catalogued");
    check(!ShardWindowsFontHiddenV2(core,9918), "System alias regression seed retained");
  }
