    check(std::bit_cast<uint32_t>(a[0])==0x35863791u && a[1]==tail && a[2]==source,"compatible-float-tail");
    const auto saved=a;
    AudioFloatsWritten(std::span(a),1,1u,0x00000000u,0x0.0p+0);
    check(a==saved,"compatible-float-repeat");
    AudioFloatsWritten(std::span(a),0,1u,0x00000000u,0x0.0p+0);
    check(a==saved,"compatible-float-zero-write");
